function flattenObject(obj, prefix = ""){const flat ={};for (const [key, value] of Object.entries(obj)){const fullKey = prefix ? `${prefix}.${key}` : key;if (value !== null && typeof value === "object" && !Array.isArray(value)){Object.assign(flat, flattenObject(value, fullKey));}else if (Array.isArray(value)){flat[fullKey] = value.map((v) => (typeof v === "object" ? JSON.stringify(v) : v)).join(";");}else{flat[fullKey] = value;}}return flat;}function csvEscape(value){const str = value === undefined || value === null ? "" : String(value);return /[",\n]/.test(str) ? `"${str.replace(/"/g, '""')}"` : str;
}

function jsonToCsv(jsonText) {
  const data = JSON.parse(jsonText);
  const rows = Array.isArray(data) ? data : [data];
  const flatRows = rows.map((r) => flattenObject(r));
  const headers = [...new Set(flatRows.flatMap((r) => Object.keys(r)))];
  const lines = [headers.map(csvEscape).join(",")];
  flatRows.forEach((row) => lines.push(headers.map((h) => csvEscape(row[h])).join(",")));
  return lines.join("\n");
}

/* Parses one CSV line into fields, respecting quoted fields that may
   contain commas or escaped ("") double quotes. */
function parseCsvLine(line) {
  const fields = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"' && line[i + 1] === '"') { current += '"'; i++; }
      else if (ch === '"') { inQuotes = false; }
      else { current += ch; }
    } else if (ch === '"') { inQuotes = true; }
    else if (ch === ",") { fields.push(current); current = ""; }
    else { current += ch; }
  }
  fields.push(current);
  return fields;
}

function coerceCsvValue(str) {
  if (str === "") return "";
  if (str === "true") return true;
  if (str === "false") return false;
  if (/^-?\d+(\.\d+)?$/.test(str)) return Number(str);
  return str;
}

function unflattenObject(flat) {
  const result = {};
  for (const [key, value] of Object.entries(flat)) {
    const parts = key.split(".");
    let node = result;
    parts.forEach((part, i) => {
      if (i === parts.length - 1) node[part] = coerceCsvValue(value);
      else node = node[part] = node[part] || {};
    });
  }
  return result;
}

function csvToJson(csvText) {
  const lines = csvText.trim().split("\n").filter(Boolean);
  if (!lines.length) return [];
  const headers = parseCsvLine(lines[0]);
  return lines.slice(1).map((line) => {
    const fields = parseCsvLine(line);
    const flat = {};
    headers.forEach((h, i) => (flat[h] = fields[i]));
    return unflattenObject(flat);
  });
}

function executeJsonCsv() {
  const raw = document.getElementById("jsoncsv-input").value;
  const mode = document.querySelector('input[name="jsoncsv-mode"]:checked').value;
  const out = document.getElementById("jsoncsv-result");
  if (!raw.trim()) { GAMA.say("idle"); out.textContent = ""; return; }
  try {
    out.textContent = mode === "json2csv" ? jsonToCsv(raw) : JSON.stringify(csvToJson(raw), null, 2);
    GAMA.say("success");
  } catch (e) {
    out.textContent = `// couldn't parse: ${e.message}`;
    GAMA.say("error");
  }
}
const executeJsonCsvDebounced = GAMA.debounce(executeJsonCsv, 300);